// Meta calls this once when you register the webhook URL.
const VERIFY_TOKEN = 'change-me-to-a-random-string';
const q = $input.first().json.query || {};
const ok = q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === VERIFY_TOKEN;
return [{ json: { status: ok ? 200 : 403, body: ok ? String(q['hub.challenge']) : 'Forbidden' } }];

// Meta signs every webhook: X-Hub-Signature-256 = HMAC SHA-256 of the raw body with the app secret.
// n8n server needs WHATSAPP_APP_SECRET, N8N_BLOCK_ENV_ACCESS_IN_NODE=false and NODE_FUNCTION_ALLOW_BUILTIN=crypto.
const crypto = require('crypto');
const item = $input.first();
const q = item.json.query || {};
const dryRun = ['1', 'true', 'yes'].includes(String(q.dry_run ?? item.json.body?.dry_run ?? '').toLowerCase());

// A dry run sends nothing and stores nothing, but it still runs the workflow, so it needs its own token:
// the X-Dry-Run-Token header must equal WHATSAPP_DRY_RUN_TOKEN. Without that variable dry runs are off.
if (dryRun) {
  let token = '';
  try { token = $env.WHATSAPP_DRY_RUN_TOKEN || ''; } catch (e) { /* env access blocked */ }
  if (!token) return [{ json: { valid: false, reason: 'dry runs are off: WHATSAPP_DRY_RUN_TOKEN is not set' } }];
  const sent = Buffer.from(String(item.json.headers?.['x-dry-run-token'] || ''));
  const wanted = Buffer.from(token);
  const ok = sent.length === wanted.length && crypto.timingSafeEqual(sent, wanted);
  return [{ json: ok ? { ...item.json, signature: 'not checked (dry run with token)', valid: true }
                     : { valid: false, reason: 'dry run token missing or wrong' } }];
}

let secret = '';
try { secret = $env.WHATSAPP_APP_SECRET || ''; } catch (e) { /* env access blocked */ }
if (!secret) return [{ json: { valid: false, reason: 'WHATSAPP_APP_SECRET is not available to n8n' } }];

const header = String(item.json.headers?.['x-hub-signature-256'] || '');
if (!header.startsWith('sha256=')) return [{ json: { valid: false, reason: 'missing signature' } }];

const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const expected = Buffer.from('sha256=' + crypto.createHmac('sha256', secret).update(raw).digest('hex'));
const given = Buffer.from(header);
const valid = given.length === expected.length && crypto.timingSafeEqual(given, expected);
return [{ json: valid ? { ...item.json, signature: 'valid', valid } : { valid: false, reason: 'signature mismatch' } }];

// Settings: edit these before going live.
const settings = {
  business_name: 'Palm Grove Realty',
  whatsapp_phone_number_id: 'YOUR_PHONE_NUMBER_ID',
  graph_api_version: 'v23.0',
  telegram_sales_chat_id: 'YOUR_SALES_CHAT_ID',
  // Haiku: short chat messages, five fields, high volume. Use claude-sonnet-5-5 if extraction misses too often.
  anthropic_model: 'claude-haiku-5-5',
  // Provider: anthropic | gemini. Gemini Flash-Lite is the Haiku-class option.
  llm_provider: 'anthropic',
  gemini_model: 'gemini-3.5-flash-lite',
};

const req = $input.first().json;
const q = req.query || {};
const body = req.body || {};
const dryRun = ['1', 'true', 'yes'].includes(String(q.dry_run ?? body.dry_run ?? '').toLowerCase());

const value = body.entry?.[0]?.changes?.[0]?.value || {};
const msg = value.messages?.[0];
if (!msg || msg.type !== 'text') {
  const reason = msg ? `unsupported message type: ${msg.type}` : 'no message (status update)';
  return [{ json: { skip: true, reason, dry_run: dryRun, settings } }];
}

const phone = '+' + String(msg.from).replace(/\D/g, '');
const name = value.contacts?.[0]?.profile?.name || '';
// Live messages continue the stored profile. A dry run reads and stores nothing: to continue a conversation,
// send the previous answer's "profile" back in the body.
const FIELDS = ['intent', 'area', 'bedrooms', 'budget_aed', 'timeline', 'language', 'messages', 'alerted'];
const given = dryRun && body.profile && typeof body.profile === 'object' ? body.profile : {};
const carried = Object.fromEntries(FIELDS.filter((k) => k in given).map((k) => [k, given[k]]));
const stored = dryRun ? null : ($getWorkflowStaticData('global').live ??= {})[phone];
const profile = stored || { phone, name, messages: 0, alerted: false, ...carried };

return [{ json: { skip: false, dry_run: dryRun, settings, phone, name: name || profile.name, text: msg.text.body, profile } }];

function claudeRequest(model, body) {
  const fallback = !/^claude-haiku/.test(model);
  return {
    claude_body: { model, ...body, ...(fallback ? { fallbacks: 'default' } : {}) },
    claude_headers: { 'anthropic-version': '2026-10-21', ...(fallback ? { 'anthropic-beta': 'server-side-fallback-2026-07-01' } : {}) },
  };
}

// Gemini's responseSchema takes the same JSON schema minus additionalProperties.
function geminiSchema(schema) {
  if (Array.isArray(schema)) return schema.map(geminiSchema);
  if (!schema || typeof schema !== 'object') return schema;
  return Object.fromEntries(Object.entries(schema).filter(([k]) => k !== 'additionalProperties').map(([k, v]) => [k, geminiSchema(v)]));
}
function llmRequest(s, { system, user, schema, max_tokens }) {
  if (s.llm_provider === 'gemini') {
    return {
      llm_provider: 'gemini',
      gemini_url: `https://generativelanguage.googleapis.com/v1beta/models/${s.gemini_model}:generateContent`,
      gemini_body: {
        systemInstruction: { parts: [{ text: system }] },
        contents: [{ role: 'user', parts: [{ text: user }] }],
        generationConfig: { responseMimeType: 'application/json', responseSchema: geminiSchema(schema) },
      },
    };
  }
  if (s.llm_provider !== 'anthropic') throw new Error(`llm_provider must be anthropic or gemini, not "${s.llm_provider}"`);
  return {
    llm_provider: 'anthropic',
    ...claudeRequest(s.anthropic_model, {
      max_tokens, output_config: { effort: 'low', format: { type: 'json_schema', schema } }, system,
      messages: [{ role: 'user', content: user }],
    }),
  };
}

// Keyword rules: used for dry runs and as the fallback when Claude fails.
const AREAS = {
  'dubai marina': 'Dubai Marina', 'دبي مارينا': 'Dubai Marina', 'marina': 'Dubai Marina',
  'jumeirah village circle': 'JVC', 'jvc': 'JVC', 'downtown': 'Downtown Dubai', 'داون تاون': 'Downtown Dubai',
  'business bay': 'Business Bay', 'الخليج التجاري': 'Business Bay', 'palm jumeirah': 'Palm Jumeirah',
  'نخلة جميرا': 'Palm Jumeirah', 'al reem': 'Al Reem Island', 'جزيرة الريم': 'Al Reem Island',
  'yas island': 'Yas Island', 'جزيرة ياس': 'Yas Island',
};

function rules(raw) {
  const t = raw
    .replace(/[٠-٩]/g, (d) => '٠١٢٣٤٥٦٧٨٩'.indexOf(d))
    .replace(/٫/g, '.')
    .replace(/(\d),(\d{3})/g, '$1$2')
    .toLowerCase();
  const arabic = (raw.match(/[؀-ۿ]/g) || []).length;
  const letters = (raw.match(/[A-Za-z؀-ۿ]/g) || []).length || 1;

  let intent = 'unknown';
  if (/(https?:\/\/|www\.)/.test(t) && /(crypto|loan|seo|followers|promotion)/.test(t)) intent = 'spam';
  else if (/\b(buy|buying|purchase|own)\b|شراء|اشتري|أشتري|تملك/.test(t)) intent = 'buy';
  else if (/\b(rent|renting|lease)\b|ايجار|إيجار|استئجار/.test(t)) intent = 'rent';
  else if (/\?|؟|price|how much|كم|سعر/.test(t)) intent = 'info';

  let bedrooms = -1;
  const b = t.match(/(\d+)\s*-?\s*(?:bed|br\b|bhk)/);
  if (b) bedrooms = Number(b[1]);
  else if (/studio|استوديو/.test(t)) bedrooms = 0;
  else if (/غرفتين/.test(t)) bedrooms = 2;
  else if (/ثلاث غرف|3 غرف/.test(t)) bedrooms = 3;
  else if (/غرفة (?:وحدة|واحدة)/.test(t)) bedrooms = 1;

  let budget = 0;
  for (const m of t.matchAll(/(\d+(?:\.\d+)?)\s*(k|m|mn|million|ألف|الف|مليون)?(?![\d])/g)) {
    const unit = m[2] || '';
    let n = Number(m[1]);
    if (['k', 'ألف', 'الف'].includes(unit)) n *= 1e3;
    if (['m', 'mn', 'million', 'مليون'].includes(unit)) n *= 1e6;
    if (n >= 10000 && n <= 100e6) budget = Math.max(budget, Math.round(n));
  }

  const area = Object.entries(AREAS).find(([k]) => t.includes(k))?.[1] || '';

  let timeline = 'unknown';
  if (/(asap|urgent|this week|this month|immediately|right away|اليوم|هالاسبوع|هذا الأسبوع|هذا الشهر|بأسرع|ضروري)/.test(t)) timeline = 'this_month';
  else if (/(next month|in (?:1|2|3|one|two|three) months?|within (?:1|2|3) months|الشهر الجاي|الشهر القادم|بعد شهرين)/.test(t)) timeline = '1_3_months';
  else if (/(next year|6 months|later|just looking|browsing|السنة الجاية|مو مستعجل)/.test(t)) timeline = 'later';

  return { intent, area, bedrooms, budget_aed: budget, timeline, language: arabic / letters > 0.3 ? 'ar' : 'en' };
}

const d = $input.first().json;
const known = (({ intent, area, bedrooms, budget_aed, timeline }) => ({ intent, area, bedrooms, budget_aed, timeline }))(d.profile);
const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['intent', 'area', 'bedrooms', 'budget_aed', 'timeline', 'language'],
  properties: {
    intent: { type: 'string', enum: ['buy', 'rent', 'info', 'spam', 'unknown'] },
    area: { type: 'string', description: 'Area or community in English, empty string if not stated' },
    bedrooms: { type: 'integer', description: '0 for studio, -1 if not stated' },
    budget_aed: { type: 'integer', description: 'Budget in AED (yearly rent or purchase price), 0 if not stated' },
    timeline: { type: 'string', enum: ['this_month', '1_3_months', 'later', 'unknown'] },
    language: { type: 'string', enum: ['en', 'ar'], description: 'Main language of the new message' },
  },
};
const request = llmRequest(d.settings, {
  max_tokens: 2048,
  schema,
  system:
    'You read WhatsApp messages sent to a real estate agency in the UAE. Messages may be in English, Arabic or both. ' +
    'Extract only what the customer states in the new message; use "unknown", "", -1 or 0 for anything not stated. ' +
    'Convert amounts to AED (120k = 120000, 1.2M = 1200000, مية وعشرين ألف = 120000). ' +
    'Messages offering loans, crypto, SEO or followers are spam.',
  user: `Known details so far: ${JSON.stringify(known)}\n\nNew message:\n${d.text}`,
});

return [{ json: { ...d, extracted: rules(d.text), extraction_source: 'rules', ...request } }];

const BLOCKED = ['SAFETY', 'PROHIBITED_CONTENT', 'BLOCKLIST', 'SPII', 'RECITATION'];
function readLLM(res) {
  if (!res || res.error) {
    const msg = res?.error?.message || JSON.stringify(res?.error);
    // n8n replaces the API message on 429, so check the whole error (status code, description, cause).
    const limited = /429|rate.?limit|RESOURCE_EXHAUSTED|quota|spacing your requests/i.test(JSON.stringify(res?.error));
    throw new Error(`${limited ? 'rate limited (429) after retries' : 'request failed'}: ${msg}`);
  }
  if (res.candidates || res.promptFeedback) {  // Gemini generateContent
    const c = res.candidates?.[0];
    if (res.promptFeedback?.blockReason || BLOCKED.includes(c?.finishReason)) throw new Error('model declined the request');
    const text = (c?.content?.parts || []).filter((p) => p.text && !p.thought).map((p) => p.text).join('');
    if (!text) throw new Error('no text in response');
    return JSON.parse(text);
  }
  if (res.stop_reason === 'refusal') throw new Error('model declined the request');  // Claude Messages
  const text = [...(res.content || [])].reverse().find((b) => b.type === 'text')?.text;
  if (!text) throw new Error('no text block in response');
  return JSON.parse(text);
}
const PROVIDER_NAME = { anthropic: 'Claude', gemini: 'Gemini' };
const SOURCE = { anthropic: 'claude', gemini: 'gemini' };

const base = $('Extract with rules').first().json;
try {
  const extracted = readLLM($input.first().json);
  return [{ json: { ...base, extracted, extraction_source: SOURCE[base.llm_provider] } }];
} catch (e) {
  return [{ json: { ...base, extraction_note: `${PROVIDER_NAME[base.llm_provider]} failed, used rules: ${e.message}` } }];
}

const d = $input.first().json;
const s = d.settings;
const e = d.extracted;
const p = { ...d.profile };

// Merge what this message added into the lead profile.
if (['buy', 'rent', 'spam'].includes(e.intent) || (e.intent === 'info' && !p.intent)) p.intent = e.intent;
if (e.area) p.area = e.area;
if (e.bedrooms >= 0) p.bedrooms = e.bedrooms;
if (e.budget_aed > 0) p.budget_aed = e.budget_aed;
if (e.timeline && e.timeline !== 'unknown') p.timeline = e.timeline;
p.language = e.language || p.language || 'en';

const isLead = ['buy', 'rent'].includes(p.intent);
const have = {
  area: !!p.area,
  bedrooms: p.bedrooms >= 0,
  budget: p.budget_aed > 0,
  timeline: !!p.timeline && p.timeline !== 'unknown',
};
let score = 'cold';
if (p.intent === 'spam') score = 'spam';
else if (isLead && have.budget && ['this_month', '1_3_months'].includes(p.timeline) && (have.area || have.bedrooms)) score = 'hot';
else if (isLead && Object.values(have).filter(Boolean).length >= 2) score = 'warm';
const missing = isLead ? ['area', 'bedrooms', 'budget', 'timeline'].filter((k) => !have[k]) : ['intent'];

const n = d.name ? ` ${d.name}` : '';
const T = {
  en: {
    greet: `Hi${n}, thanks for contacting ${s.business_name}. `,
    intent: 'Are you looking to buy or rent?',
    area: 'Which area or community do you prefer?',
    bedrooms: 'How many bedrooms do you need?',
    budget: p.intent === 'rent' ? 'What is your yearly budget in AED?' : 'What is your budget in AED?',
    timeline: p.intent === 'rent' ? 'When are you planning to move in?' : 'When are you planning to buy?',
    hot: `Thank you${n}. An advisor will call you within 15 minutes.`,
    done: `Thank you${n}. An advisor will contact you today with options.`,
  },
  ar: {
    greet: `أهلاً${n}، شكراً لتواصلك مع ${s.business_name}. `,
    intent: 'هل تبحث عن شراء أو إيجار؟',
    area: 'أي منطقة أو مجمع تفضل؟',
    bedrooms: 'كم عدد الغرف التي تحتاجها؟',
    budget: p.intent === 'rent' ? 'كم ميزانيتك السنوية بالدرهم؟' : 'كم ميزانيتك بالدرهم؟',
    timeline: p.intent === 'rent' ? 'متى تخطط للانتقال؟' : 'متى تخطط للشراء؟',
    hot: `شكراً لك${n}. سيتصل بك أحد مستشارينا خلال 15 دقيقة.`,
    done: `شكراً لك${n}. سيتواصل معك أحد مستشارينا اليوم بالخيارات المناسبة.`,
  },
}[p.language === 'ar' ? 'ar' : 'en'];

let reply = null;
if (score !== 'spam') {
  const next = score === 'hot' ? T.hot : missing.length ? T[missing[0]] : T.done;
  reply = (p.messages === 0 ? T.greet : '') + next;
}

const alert = score === 'hot' && !p.alerted;
if (alert) p.alerted = true;
p.messages += 1;
p.last_message = d.text;
p.updated_at = new Date().toISOString();

// Only live messages are stored.
if (!d.dry_run) {
  const store = $getWorkflowStaticData('global');
  (store.live ??= {})[d.phone] = p;
  delete store.dry;  // profiles kept by earlier versions of the dry run
}

const digits = d.phone.replace(/\D/g, '');
const alert_text = [
  `Hot lead: ${d.name || d.phone}`,
  `${p.intent} | ${p.area || 'area ?'} | ${p.bedrooms >= 0 ? p.bedrooms + ' BR' : 'BR ?'} | AED ${p.budget_aed || '?'} | ${p.timeline || '?'}`,
  `Last message: "${d.text}"`,
  `Chat: https://wa.me/${digits}`,
].join('\n');

return [{ json: {
  dry_run: d.dry_run, phone: d.phone, name: d.name, score, missing, profile: p,
  reply_text: reply, alert, alert_text,
  extraction_source: d.extraction_source, extraction_note: d.extraction_note || '',
  whatsapp_body: reply ? { messaging_product: 'whatsapp', recipient_type: 'individual', to: digits, type: 'text', text: { preview_url: false, body: reply } } : null,
} }];
